class InlineProductSpec(BaseModel):
    """
    A product defined inline on a link create, resolved by its natural `key`. A new key creates the product; a known key reuses it, and pricing that differs from the current version publishes a NEW version. That bump is safe because the link created here pins the version it got, so links already in circulation keep selling what they advertised.

    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    base_price: Optional[str] = Field(
        None,
        alias="basePrice",
        description="Decimal string. Money never crosses the wire as a float.",
    )
    billing_cycle: Optional[Literal["weekly", "monthly", "annual"]] = Field(
        None,
        alias="billingCycle",
        description="Required for subscription/prepaid, optional for usage, forbidden for one_time.",
    )
    currency: Optional[str] = Field(None, max_length=3, min_length=3)
    description: Optional[str] = None
    key: str = Field(
        ...,
        description="Stable per-tenant natural key. Required — it is what makes creating a link for the same product twice resolve to one product, not two.\n",
    )
    meters: Optional[list[InlineMeterSpec]] = Field(
        None,
        description="Meters defined on the product, created once by name. An existing meter is never rewritten: its `name` is the key `track()` ingests against and its `aggregation` decides how past events were counted, so changing either here would retroactively alter what recorded usage meant.\n",
    )
    name: Optional[str] = Field(
        None, description="Display name. Defaults to `key` when omitted."
    )
    prices: Optional[list[InlinePriceSpec]] = Field(
        None,
        description='Prices on the version being published, declared in full. A set that differs from what the current version carries publishes a NEW version, the same as a differing `basePrice` — pricing is immutable once published. Omit the field entirely to say nothing about prices; an empty array means "no prices".\n',
    )
    pricing_model: Literal["subscription", "one_time", "usage", "prepaid"] = Field(
        ..., alias="pricingModel"
    )
    type: Optional[Literal["agent", "item"]] = None


