class PriceOption(BaseModel):
    """
    A product's price option (ADR 0062): "Mensal", "Anual", "Vitalício". Its terms are versions; `version` is the current one, the newest published. Editing a sold option publishes a new version and whoever pinned the old one keeps it.

    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    archived: bool = Field(..., description="Sells to nobody new.")
    hidden: bool = Field(
        ...,
        description="Left off the store page and the product page; it still sells through its own link.",
    )
    id: str
    is_default: bool = Field(
        ...,
        alias="isDefault",
        description="What a buyer gets when nothing names an option.",
    )
    name: str = Field(..., max_length=60)
    position: int
    usage: Optional[list[Price]] = Field(
        None,
        description="What the current version charges per meter (its meter prices).",
    )
    version: Optional[Version] = None


class PriceOptionList(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    options: list[PriceOption]


